    if extension_target is None:
        raise RuntimeError("could not locate the built Python extension target")
    run_build([ninja, "-C", str(BUILD_ROOT), extension_target])
    extension = BUILD_ROOT / extension_target.replace("/", os.sep)
    if not extension.exists():
        raise RuntimeError(f"built extension was not found: {extension}")
    return extension


def _import_calculator(extension: Path):
    if hasattr(os, "add_dll_directory"):
        os.add_dll_directory(str(extension.parent.parent.parent))
        for compiler in ("gcc", "gfortran"):
            executable = shutil.which(compiler)
            if executable:
                os.add_dll_directory(str(Path(executable).resolve().parent))
    else:
        # Meson leaves a ``.so.p`` target directory beside the actual shared
        # library.  Only pass a regular file to dlopen on Linux.
        library = next(
            (
                candidate
                for candidate in sorted(BUILD_ROOT.glob("libtblite*.so*"))
                if candidate.is_file()
            ),
            None,
        )
        if library is not None:
            ctypes.CDLL(str(library), mode=ctypes.RTLD_GLOBAL)
    sys.path.insert(0, str(SOURCE_ROOT / "python"))
    import tblite  # type: ignore[import-not-found]

    tblite.__path__.insert(0, str(extension.parent))
    from ase import Atoms  # type: ignore[import-not-found]
    from tblite.ase import TBLite  # type: ignore[import-not-found]

    return Atoms, TBLite


def _case(Atoms):
    symbols = "C2N2O4"
    positions = np.asarray(
        [
            [0.0, 0.0, 0.0],
            [1.45, 0.0, 0.0],
            [2.50, 0.80, 0.0],
            [2.50, -0.80, 0.0],
            [-1.00, 0.80, 0.0],
            [-1.00, -0.80, 0.0],
            [0.0, 0.0, 1.20],
            [1.45, 0.0, 1.20],
        ],
        dtype=float,
    )
    cell = np.diag([8.0, 8.0, 8.0])
    return Atoms(symbols, positions=positions, cell=cell, pbc=True), (2, 2, 2)


def main() -> int:
    try:
        extension = _build_extension()
        Atoms, TBLite = _import_calculator(extension)
        unit, repeat = _case(Atoms)
        unit.calc = TBLite(method="GFN2-xTB", accuracy=0.1, verbosity=0)
        unit_energy = float(unit.get_potential_energy())
        forces = np.asarray(unit.get_forces(), dtype=float)
        stress = np.asarray(unit.get_stress(), dtype=float)
        repeated = unit.repeat(repeat)
        repeated.calc = TBLite(method="GFN2-xTB", accuracy=0.1, verbosity=0)
        repeated_energy = float(repeated.get_potential_energy())
        finite = bool(
            np.isfinite(unit_energy)
            and np.isfinite(repeated_energy)
            and np.all(np.isfinite(forces))
            and np.all(np.isfinite(stress))
        )
        if not finite:
            raise ArithmeticError("the periodic calculation produced a non-finite observable")
        return write_report(
            {
                "schema_version": "1.0",
                "status": "workflow_completed",
                "observation": {
                    "method": "GFN2-xTB",
                    "atom_count_unit": len(unit),
                    "atom_count_repeated": len(repeated),
                    "cell_volume_unit_A3": float(unit.get_volume()),
                    "unit_energy_eV": unit_energy,
                    "repeated_calculation_finite": bool(np.isfinite(repeated_energy)),
                    "max_force_eV_per_A": float(np.max(np.abs(forces))),
                    "max_stress_eV_per_A3": float(np.max(np.abs(stress))),
                    "all_observables_finite": finite,
                },
            },
            0,
        )
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )


if __name__ == "__main__":
    raise SystemExit(main())

